/** @import { EditorSelectionMarkers } from './selection.js'; */

import $ from '@fr0st/query';
import { containsNode } from './helpers.js';

const transparent = 'rgba(0, 0, 0, 0)';
const mergeSelector = [
    'a', 'b', 'bdi', 'bdo', 'cite', 'code', 'del', 'em', 'i', 'ins', 'kbd',
    'mark', 's', 'samp', 'small', 'span', 'strong', 'sub', 'sup', 'u', 'var',
].join(', ');
const phrasingSelector = [
    'a', 'abbr', 'area', 'audio', 'b', 'bdi', 'bdo', 'br', 'button',
    'cite', 'code', 'data', 'datalist', 'del', 'dfn', 'em', 'embed', 'i', 'iframe',
    'img', 'input', 'ins', 'kbd', 'label', 'map', 'mark', 'math', 'meter',
    'noscript', 'object', 'output', 'picture', 'progress', 'q', 'ruby', 's',
    'samp', 'script', 'select', 'slot', 'small', 'span', 'strong', 'sub', 'sup',
    'svg', 'template', 'textarea', 'time', 'u', 'var', 'video', 'wbr',
].join(', ');

/**
 * Determines whether a node can stay in an inline run, including comments.
 * https://html.spec.whatwg.org/multipage/dom.html#phrasing-content
 * @param {Node} node The input node.
 * @returns {boolean} Whether the node is phrasing content.
 */
export const isPhrasingContent = (node) => $._isText(node) || node.nodeType === 8 || $.is(node, phrasingSelector);

/**
 * Joins adjacent inline formatting elements without merging media or other structured content.
 * @param {HTMLElement} container The container.
 * @param {EditorSelectionMarkers} markers The selection markers.
 */
export function joinAdjacentNodes(container, markers) {
    const elements = $.find(mergeSelector, container);
    const isMarker = (node) => node === markers.start || node === markers.end;

    for (const element of elements) {
        if (!containsNode(container, element)) {
            continue;
        }

        const moveMarkers = [];
        let next = element.nextSibling;

        while (next && isMarker(next)) {
            moveMarkers.push(next);
            next = next.nextSibling;
        }

        if (!next || !$.isEqual(element, next, { shallow: true })) {
            continue;
        }

        $.prepend(next, [...$.contents(element), ...moveMarkers]);
        $.detach(element);
    }
}

/**
 * Normalizes phrasing containers.
 * @param {HTMLElement} container The container.
 */
export function normalizePhrasing(container) {
    const elements = $.find('h1, h2, h3, h4, h5, h6, p, pre', container);

    for (const element of elements) {
        if (!containsNode(container, element)) {
            continue;
        }

        const contents = $.contents(element);

        if (!contents.length) {
            continue;
        }

        for (const [i, child] of contents.entries()) {
            if (isPhrasingContent(child)) {
                continue;
            }

            // Lift the first nested block and everything after it out of its parent.
            const nextSiblings = contents.splice(i);

            $.after(element, nextSiblings);

            const tagName = $.tagName(element);

            // Rewrap inline runs while carrying the original formatting into nested blocks.
            const wrapContents = (parent, nodes) => {
                const stack = [];
                let lastNode;

                for (const node of nodes) {
                    if (isPhrasingContent(node)) {
                        stack.push(node);
                        continue;
                    }

                    if (stack.length) {
                        const clone = $.clone(element, { deep: false });
                        const tempNodes = stack.splice(0);

                        $.append(clone, tempNodes);
                        $.before(node, clone);
                    }

                    lastNode = node;

                    if ($.is(element, 'p') || $.is(node, tagName)) {
                        continue;
                    }

                    if ($.is(node, 'h1, h2, h3, h4, h5, h6, p, pre')) {
                        const clone = $.clone(element, { deep: false });
                        const styles = { ...$.getStyle(node), ...$.getStyle(clone) };

                        $.before(node, clone);
                        $.setStyle(clone, styles);
                        $.append(clone, $.contents(node));
                        $.detach(node);
                        lastNode = clone;
                        continue;
                    }

                    wrapContents(node, $.contents(node));
                }

                if (stack.length) {
                    const clone = $.clone(element, { deep: false });

                    $.append(clone, stack);

                    if (lastNode) {
                        $.after(lastNode, clone);
                    } else {
                        $.append(parent, clone);
                    }
                }
            };

            wrapContents(element, nextSiblings);
            break;
        }

        if (!contents.length) {
            $.detach(element);
        }
    }
}

/**
 * Normalizes span elements.
 * @param {HTMLElement} container The container.
 */
export function normalizeSpans(container) {
    const elements = $.find('span', container);

    for (const element of elements) {
        if ($.getProperty(element, 'attributes').length) {
            continue;
        }

        const contents = $.contents(element);

        if (contents.length) {
            $.after(element, contents);
        }

        $.detach(element);
    }
}

/**
 * Normalizes style attributes.
 * @param {HTMLElement} container The container.
 */
export function normalizeStyles(container) {
    const elements = $.find('[style]', container);

    for (const element of elements) {
        const styles = $.getStyle(element);

        for (const style of Object.keys(styles)) {
            const clone = $.clone(element, { deep: false });

            $.after(element, clone);
            $.removeAttribute(clone, 'style');

            let testValue = $.css(clone, style);

            $.detach(clone);

            if (style === 'background-color' && testValue === transparent) {
                testValue = [container, ...$.parents(element, null, container)]
                    .map((parent) => $.css(parent, style))
                    .filter((parentStyle) => parentStyle !== transparent)
                    .pop();
            }

            const cssValue = $.css(element, style);

            if (cssValue === testValue) {
                $.removeStyle(element, style);
            }
        }

        if ($.getAttribute(element, 'style') === '') {
            $.removeAttribute(element, 'style');
        }
    }
}
